class Solution {
public:
    int findMinimumTime(std::vector<std::vector<int>>& tasks) {
        std::sort(tasks.begin(), tasks.end(), [](const auto& a, const auto& b) {
            return a[1] < b[1];
        });
        std::vector<bool> used(2005, false);
        for (const auto& task : tasks) {
            int start = task[0], end = task[1], duration = task[2];
            int already = 0;
            for (int t = start; t <= end; ++t) {
                if (used[t]) already++;
            }
            int needed = duration - already;
            int t = end;
            while (needed > 0) {
                if (!used[t]) {
                    used[t] = true;
                    needed--;
                }
                t--;
            }
        }
        int ans = 0;
        for (bool b : used) if (b) ans++;
        return ans;
    }
};

class Solution {
    public int findMinimumTime(int[][] tasks) {
        java.util.Arrays.sort(tasks, (a, b) -> Integer.compare(a[1], b[1]));
        boolean[] used = new boolean[2005];
        for (int[] task : tasks) {
            int start = task[0], end = task[1], duration = task[2];
            int already = 0;
            for (int t = start; t <= end; t++) {
                if (used[t]) already++;
            }
            int needed = duration - already;
            int t = end;
            while (needed > 0) {
                if (!used[t]) {
                    used[t] = true;
                    needed--;
                }
                t--;
            }
        }
        int ans = 0;
        for (boolean b : used) if (b) ans++;
        return ans;
    }
}

var findMinimumTime = function(tasks) {
    tasks.sort((a, b) => a[1] - b[1]);
    const used = new Uint8Array(2005);
    for (const [start, end, duration] of tasks) {
        let already = 0;
        for (let t = start; t <= end; t++) {
            if (used[t]) already++;
        }
        let needed = duration - already;
        let t = end;
        while (needed > 0) {
            if (!used[t]) {
                used[t] = 1;
                needed--;
            }
            t--;
        }
    }
    let ans = 0;
    for (let i = 0; i < used.length; i++) ans += used[i];
    return ans;
};
